namespace sv_18f1074f0c2a44a190b581732e823ea1.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Patel"] = ["9:30 AM", "10:00 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Williams"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    // Doctors that do NOT accept self-pay
    private static readonly HashSet<string> NoSelfPay = ["Dr. Smith"];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(new List<string>(slots));
        }

        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient + appointment details server-side.
    /// Returns a dictionary of field name → error message for any validation failures.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Simulate outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Self-pay restriction
        if (insuranceProvider == "None" && NoSelfPay.Contains(doctor))
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on time slot
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_18f1074f0c2a44a190b581732e823ea1.Models;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Required(ErrorMessage = "Phone number is required.")]
    public string Phone { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select an insurance provider.")]
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = string.Empty;

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = string.Empty;

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
    public string ReasonForVisit { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_18f1074f0c2a44a190b581732e823ea1.Models
@using sv_18f1074f0c2a44a190b581732e823ea1.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Appointment Confirmed!</h4>
        <p>Thank you, <strong>@model.PatientName</strong>. Your appointment with <strong>@model.Doctor</strong> on <strong>@model.AppointmentDate?.ToString("MMMM d, yyyy")</strong> at <strong>@model.TimeSlot</strong> has been booked.</p>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">

        @* ───── STEP 1 ───── *@
        <div class="card mb-4">
            <div class="card-header"><strong>Step 1:</strong> Patient Information</div>
            <div class="card-body">
                <div class="mb-3">
                    <label for="patientName" class="form-label">Patient Name</label>
                    <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
                    <ValidationMessage For="() => model.PatientName" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email</label>
                    <InputText id="email" class="form-control" @bind-Value="model.Email" />
                    <ValidationMessage For="() => model.Email" />
                </div>

                <div class="mb-3">
                    <label for="phone" class="form-label">Phone</label>
                    <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
                    <ValidationMessage For="() => model.Phone" />
                </div>

                <div class="mb-3">
                    <label for="insurance" class="form-label">Insurance Provider</label>
                    <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                        <option value="">-- Select --</option>
                        <option value="Aetna">Aetna</option>
                        <option value="BlueCross">BlueCross</option>
                        <option value="Cigna">Cigna</option>
                        <option value="UnitedHealth">UnitedHealth</option>
                        <option value="None">None</option>
                    </InputSelect>
                    <ValidationMessage For="() => model.InsuranceProvider" />
                </div>

                @if (!showStep2)
                {
                    <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                        Next &rarr;
                    </button>
                }
            </div>
        </div>

        @* ───── STEP 2 ───── *@
        @if (showStep2)
        {
            <div class="card mb-4">
                <div class="card-header"><strong>Step 2:</strong> Appointment Details</div>
                <div class="card-body">
                    <div class="mb-3">
                        <label for="doctor" class="form-label">Preferred Doctor</label>
                        <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                                     @bind-Value:after="OnDoctorChanged">
                            <option value="">-- Select --</option>
                            @foreach (var doc in doctors)
                            {
                                <option value="@doc">@doc</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => model.Doctor" />
                    </div>

                    <div class="mb-3">
                        <label for="date" class="form-label">Date</label>
                        <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                                   @bind-Value:after="OnDateChanged" />
                        <ValidationMessage For="() => model.AppointmentDate" />
                        @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                        {
                            <div class="text-danger">Date must be in the future.</div>
                        }
                    </div>

                    <div class="mb-3">
                        <label for="timeSlot" class="form-label">Time Slot</label>
                        <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                            <option value="">-- Select --</option>
                            @foreach (var slot in availableSlots)
                            {
                                <option value="@slot">@slot</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => model.TimeSlot" />
                    </div>

                    <div class="mb-3">
                        <label for="reason" class="form-label">Reason for Visit</label>
                        <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.ReasonForVisit" />
                        <ValidationMessage For="() => model.ReasonForVisit" />
                        <small class="text-muted">@(model.ReasonForVisit?.Length ?? 0) / 500</small>
                    </div>

                    <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
                        &larr; Back
                    </button>
                    <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability" disabled="@isChecking">
                        @(isChecking ? "Checking…" : "Check Availability")
                    </button>
                    <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                        Book Appointment
                    </button>
                </div>
            </div>
        }

        <DataAnnotationsValidator />
    </EditForm>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool isSubmitted;
    private bool isChecking;
    private bool availabilityChecked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            availabilityChecked = false;
        };

        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();
        editContext.Validate();

        // Only check step-1 fields
        bool step1Valid = !editContext.GetValidationMessages()
            .Any() || !Step1Fields.Any(f =>
                editContext.GetValidationMessages(editContext.Field(f)).Any());

        // More precise: check that no step-1 field has errors
        step1Valid = !Step1Fields.Any(f =>
            editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDoctorChanged()
    {
        availabilityChecked = false;
        model.TimeSlot = string.Empty;
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        availabilityChecked = false;
        model.TimeSlot = string.Empty;
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        availabilityChecked = false;

        // Validate date is in the future
        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            messageStore.Add(editContext.Field(nameof(AppointmentModel.AppointmentDate)),
                "Date must be in the future.");
            editContext.NotifyValidationStateChanged();
            return;
        }

        // Run DataAnnotations on step-2 fields first
        editContext.Validate();
        bool hasStep2Errors = new[]
        {
            nameof(AppointmentModel.Doctor),
            nameof(AppointmentModel.AppointmentDate),
            nameof(AppointmentModel.TimeSlot),
            nameof(AppointmentModel.ReasonForVisit)
        }.Any(f => editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (hasStep2Errors)
        {
            return;
        }

        isChecking = true;
        try
        {
            var serverErrors = await AppointmentSvc.ValidatePatientAsync(
                model.Email,
                model.InsuranceProvider,
                model.Doctor,
                model.TimeSlot);

            if (serverErrors.Count > 0)
            {
                foreach (var (field, error) in serverErrors)
                {
                    messageStore.Add(editContext.Field(field), error);
                }
                editContext.NotifyValidationStateChanged();
            }
            else
            {
                availabilityChecked = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked)
        {
            isSubmitted = true;
        }
    }
}

